package rules

import "testing"

// TestLineLength ports Symplify LineLengthFixerTest: every Fixture/*.php.inc
// case, before -> after (or unchanged for the correct/skip fixtures).
func TestLineLength(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name string
		in   string
		want string
	}{
		{"break_attribute", "<?php\n\n#[SomeObject($someLongArgument, $someLongArgument, $anotherLongArgument, $anotherLongArgument, $passTheLimit, $passTheLimit, $passTheLimit)]\nclass SomeClass\n{\n\n}\n\n?>\n", "<?php\n\n#[SomeObject(\n    $someLongArgument,\n    $someLongArgument,\n    $anotherLongArgument,\n    $anotherLongArgument,\n    $passTheLimit,\n    $passTheLimit,\n    $passTheLimit\n)]\nclass SomeClass\n{\n\n}\n\n?>\n"},
		{"break_method_call_with_array", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        $this->someFunction(['foo', 'bar'], ['fooooooooooooooooo', 'baaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaar']);\n    }\n}\n\n?>\n", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        $this->someFunction(\n            ['foo', 'bar'],\n            ['fooooooooooooooooo', 'baaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaar']\n        );\n    }\n}\n\n?>\n"},
		{"break_new_some_object", "<?php\n\n$someObject = new SomeObject($someLongArgument, $someLongArgument, $anotherLongArgument, $anotherLongArgument, $passTheLimit);\n\n$someObject = new SomeObject($someLongArgument, $someLongArgument, $anotherLongArgument, $anotherLongArgument, $limits);\n\n?>\n", "<?php\n\n$someObject = new SomeObject(\n    $someLongArgument,\n    $someLongArgument,\n    $anotherLongArgument,\n    $anotherLongArgument,\n    $passTheLimit\n);\n\n$someObject = new SomeObject($someLongArgument, $someLongArgument, $anotherLongArgument, $anotherLongArgument, $limits);\n\n?>\n"},
		{"correct", "<?php\n\ndeclare(strict_types=1);\n\nclass SomeFixer\n{\n    public function getDefinition(): FixerDefinitionInterface\n    {\n        return new FixerDefinition('Class should have suffix by parent class/interface', [\n            new CodeSample(\n                <<<CODE\n<?php\n\nclass SomeClass extends Command\n{\n}\nCODE\n            ),\n        ]);\n    }\n}\n", "<?php\n\ndeclare(strict_types=1);\n\nclass SomeFixer\n{\n    public function getDefinition(): FixerDefinitionInterface\n    {\n        return new FixerDefinition('Class should have suffix by parent class/interface', [\n            new CodeSample(\n                <<<CODE\n<?php\n\nclass SomeClass extends Command\n{\n}\nCODE\n            ),\n        ]);\n    }\n}\n"},
		{"correct10", "<?php\n\ndeclare(strict_types=1);\n\nnamespace Pehapkari\\Website\\Tests\\Posts\\Year2016\\EventDispatcher;\n\nfinal class EventDispatchingTest\n{\n    public function test(): void\n    {\n        $this->someMethod(10, function () {\n           return 5;\n        });\n    }\n}\n", "<?php\n\ndeclare(strict_types=1);\n\nnamespace Pehapkari\\Website\\Tests\\Posts\\Year2016\\EventDispatcher;\n\nfinal class EventDispatchingTest\n{\n    public function test(): void\n    {\n        $this->someMethod(10, function () {\n           return 5;\n        });\n    }\n}\n"},
		{"correct11", "<?php\n\ndeclare(strict_types=1);\n\nclass ListDataProvider\n{\n    public function createListDataDTOForGroup(PlayerGroup $group): void\n    {\n        $group->prefixDefaultPaginatorOptions(\"group{$group->getId()}\");\n    }\n}\n", "<?php\n\ndeclare(strict_types=1);\n\nclass ListDataProvider\n{\n    public function createListDataDTOForGroup(PlayerGroup $group): void\n    {\n        $group->prefixDefaultPaginatorOptions(\"group{$group->getId()}\");\n    }\n}\n"},
		{"correct12", "<?php\n\ndeclare(strict_types=1);\n\nclass A\n{\n    public function __construct($orWhere)\n    {\n        $sql = 'UPDATE answer \n                SET score = score + __points__ * (\n                        SELECT COUNT(aa.id) \n                        FROM answer_to_answer_definition aa \n                        WHERE answer.id = aa.pickX_answer_id AND ('.implode(' OR ', $orWhere).')\n                ).';\n    }\n}", "<?php\n\ndeclare(strict_types=1);\n\nclass A\n{\n    public function __construct($orWhere)\n    {\n        $sql = 'UPDATE answer \n                SET score = score + __points__ * (\n                        SELECT COUNT(aa.id) \n                        FROM answer_to_answer_definition aa \n                        WHERE answer.id = aa.pickX_answer_id AND ('.implode(' OR ', $orWhere).')\n                ).';\n    }\n}"},
		{"correct2", "<?php\n\ndeclare(strict_types=1);\n\nnamespace Symplify\\BetterPhpDocParser;\n\nuse phpDocumentor\\Reflection\\DocBlock;\nuse phpDocumentor\\Reflection\\DocBlock\\Serializer;\nuse Symplify\\BetterPhpDocParser\\Renderer\\OriginalSpacingCompleter;\nuse Symplify\\PackageBuilder\\Reflection\\PrivatesCaller;\n\nfinal class FixedSerializer extends Serializer\n{\n    public function getDocComment(DocBlock $docBlock): string\n    {\n        // tags\n        $comment = (new OriginalSpacingCompleter())->completeTagSpaces($comment, $this->originalContent);\n    }\n}\n", "<?php\n\ndeclare(strict_types=1);\n\nnamespace Symplify\\BetterPhpDocParser;\n\nuse phpDocumentor\\Reflection\\DocBlock;\nuse phpDocumentor\\Reflection\\DocBlock\\Serializer;\nuse Symplify\\BetterPhpDocParser\\Renderer\\OriginalSpacingCompleter;\nuse Symplify\\PackageBuilder\\Reflection\\PrivatesCaller;\n\nfinal class FixedSerializer extends Serializer\n{\n    public function getDocComment(DocBlock $docBlock): string\n    {\n        // tags\n        $comment = (new OriginalSpacingCompleter())->completeTagSpaces($comment, $this->originalContent);\n    }\n}\n"},
		{"correct3", "<?php\n\ndeclare(strict_types=1);\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        $this->assertSame([\n            'one' => 1,\n            'two' => 2,\n        ], $parameterProvider->provide());\n    }\n}\n", "<?php\n\ndeclare(strict_types=1);\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        $this->assertSame([\n            'one' => 1,\n            'two' => 2,\n        ], $parameterProvider->provide());\n    }\n}\n"},
		{"correct4", "<?php\n\ndeclare(strict_types=1);\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        $this->assertSame([\n            'one' => 1,\n            'two' => 2,\n        ], $parameterProvider->provide());\n\n        $this->easyCodingStandardStyle->error(sprintf(\n            'Found %d error%s.',\n            $errorCount,\n            $errorCount === 1 ? '' : 's'\n        ));\n    }\n}\n", "<?php\n\ndeclare(strict_types=1);\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        $this->assertSame([\n            'one' => 1,\n            'two' => 2,\n        ], $parameterProvider->provide());\n\n        $this->easyCodingStandardStyle->error(sprintf(\n            'Found %d error%s.',\n            $errorCount,\n            $errorCount === 1 ? '' : 's'\n        ));\n    }\n}\n"},
		{"correct5", "<?php\n\ndeclare(strict_types=1);\n\nfinal class BasicallyAnyClass\n{\n    private function shouldSkip()\n    {\n    }\n\n    private function removeTagForMissingParameters(MethodWrapper $methodWrapper, DocBlockWrapper $docBlockWrapper): void\n    {\n    }\n}\n", "<?php\n\ndeclare(strict_types=1);\n\nfinal class BasicallyAnyClass\n{\n    private function shouldSkip()\n    {\n    }\n\n    private function removeTagForMissingParameters(MethodWrapper $methodWrapper, DocBlockWrapper $docBlockWrapper): void\n    {\n    }\n}\n"},
		{"correct6", "<?php\n\ndeclare(strict_types=1);\n\n$array = [1 => 'looooooooooooooooooooooooooongArraaaaaaaaaaay', 2 => 'looooooooooooooooooooooooooooongArraaaaaaaaaaay'];\n", "<?php\n\ndeclare(strict_types=1);\n\n$array = [1 => 'looooooooooooooooooooooooooongArraaaaaaaaaaay', 2 => 'looooooooooooooooooooooooooooongArraaaaaaaaaaay'];\n"},
		{"correct7", "<?php\n\ndeclare(strict_types=1);\n\n$array = [\n    'looooooooooooooooooooooooooooooooongArraaaaaaaaaaay',\n    'looooooooooooooooooooooooooooooooongArraaaaaaaaaaaaaaay'\n];\n", "<?php\n\ndeclare(strict_types=1);\n\n$array = [\n    'looooooooooooooooooooooooooooooooongArraaaaaaaaaaay',\n    'looooooooooooooooooooooooooooooooongArraaaaaaaaaaaaaaay'\n];\n"},
		{"correct8", "<?php\n\ndeclare(strict_types=1);\n\nnamespace Pehapkari\\Website\\Tests\\Posts\\Year2016\\EventDispatcher;\n\nfinal class EventDispatchingTest\n{\n    public function test(): void\n    {\n        $notifyMeOnVideoPublishedEventSubscriber = new NotifyMeOnVideoPublishedEventSubscriber;\n        $eventDispatcher->addSubscriber($notifyMeOnVideoPublishedEventSubscriber);\n    }\n}\n", "<?php\n\ndeclare(strict_types=1);\n\nnamespace Pehapkari\\Website\\Tests\\Posts\\Year2016\\EventDispatcher;\n\nfinal class EventDispatchingTest\n{\n    public function test(): void\n    {\n        $notifyMeOnVideoPublishedEventSubscriber = new NotifyMeOnVideoPublishedEventSubscriber;\n        $eventDispatcher->addSubscriber($notifyMeOnVideoPublishedEventSubscriber);\n    }\n}\n"},
		{"correct9", "<?php\n\ndeclare(strict_types=1);\n\nnamespace Pehapkari\\Website\\Tests\\Posts\\Year2016\\EventDispatcher;\n\nfinal class EventDispatchingTest\n{\n    public function test(): void\n    {\n        $this->someMethod(function () {\n           return 5;\n        });\n    }\n}\n", "<?php\n\ndeclare(strict_types=1);\n\nnamespace Pehapkari\\Website\\Tests\\Posts\\Year2016\\EventDispatcher;\n\nfinal class EventDispatchingTest\n{\n    public function test(): void\n    {\n        $this->someMethod(function () {\n           return 5;\n        });\n    }\n}\n"},
		{"correct_heredoc", "<?php\n\ndeclare(strict_types=1);\n\nnamespace Rector\\Php\\Rector\\FuncCall;\n\nfinal class SensitiveDefineRector\n{\n    public function getNowDoc()\n    {\n        return new RectorDefinition(\n            [new CodeSample(\n                <<<'PHP'\ndefine('FOO', 42, true); \nPHP\n            )]\n        );\n    }\n\n    public function getHereDoc()\n    {\n        return new RectorDefinition(\n            [new CodeSample(\n                <<<PHP\ndefine('FOO', 42, true); \nPHP\n            )]\n        );\n    }\n}\n\n?>\n", "<?php\n\ndeclare(strict_types=1);\n\nnamespace Rector\\Php\\Rector\\FuncCall;\n\nfinal class SensitiveDefineRector\n{\n    public function getNowDoc()\n    {\n        return new RectorDefinition([new CodeSample(<<<'PHP'\ndefine('FOO', 42, true); \nPHP\n            )]);\n    }\n\n    public function getHereDoc()\n    {\n        return new RectorDefinition([new CodeSample(<<<PHP\ndefine('FOO', 42, true); \nPHP\n            )]);\n    }\n}\n\n?>\n"},
		{"inline_new_arguments", "<?php\n\n$someObject = new SomeClass(\n    $someLongArgument,\n    $anotherLongArgument\n);\n\n?>\n", "<?php\n\n$someObject = new SomeClass($someLongArgument, $anotherLongArgument);\n\n?>\n"},
		{"method_call_arguments", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        $this->someFunctionCall($someLoooooooooooooongArgument, $anotherLoooooooooooooooooooooooooooooooooooongArgumentTo);\n\n        $this->someOtherFunctionCall(\n            $superShort,\n            $anotherShort\n        );\n    }\n}\n\n?>\n", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        $this->someFunctionCall(\n            $someLoooooooooooooongArgument,\n            $anotherLoooooooooooooooooooooooooooooooooooongArgumentTo\n        );\n\n        $this->someOtherFunctionCall($superShort, $anotherShort);\n    }\n}\n\n?>\n"},
		{"skip_correct_file", "<?php\n\nclass Foo\n{\n    public function render(AbstractFile $file, array $parameters): string\n    {\n        return $this->codeBlocksProtector->protectContentFromCallback($file->getContent(), function (string $content) use (\n            $file,\n            $parameters\n        ) {\n            return '...';\n        });\n    }\n}\n", "<?php\n\nclass Foo\n{\n    public function render(AbstractFile $file, array $parameters): string\n    {\n        return $this->codeBlocksProtector->protectContentFromCallback($file->getContent(), function (string $content) use (\n            $file,\n            $parameters\n        ) {\n            return '...';\n        });\n    }\n}\n"},
		{"skip_property_promotion", "<?php\n\ndeclare(strict_types=1);\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\LineLength\\LineLengthFixer\\Fixture;\n\nfinal class SkipPropertyPromotion\n{\n    public function __construct(\n        public int $value,\n        public int $name\n    ) {\n    }\n}\n", "<?php\n\ndeclare(strict_types=1);\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\LineLength\\LineLengthFixer\\Fixture;\n\nfinal class SkipPropertyPromotion\n{\n    public function __construct(\n        public int $value,\n        public int $name\n    ) {\n    }\n}\n"},
		{"skip_valid_attribute", "<?php\n\ndeclare(strict_types=1);\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\LineLength\\LineLengthFixer\\Fixture;\n\nuse Doctrine\\ORM\\Mapping\\Entity;\n\n#[Entity]\nclass SkipValidAttribute\n{\n}\n", "<?php\n\ndeclare(strict_types=1);\n\nnamespace Symplify\\CodingStandard\\Tests\\Fixer\\LineLength\\LineLengthFixer\\Fixture;\n\nuse Doctrine\\ORM\\Mapping\\Entity;\n\n#[Entity]\nclass SkipValidAttribute\n{\n}\n"},
		{"use_arguments", "<?php\n\nclass SomeClass\n{\n    public function someFunction() {\n        $someLongVariableName = $anotherLongVariableName = $yetAnotherLongVariableName = $andOneMoreLongVariableName = null;\n\n        return function () use ($someLongVariableName, $anotherLongVariableName, $yetAnotherLongVariableName, $andOneMoreLongVariableName) {};\n\n        return function ($argument) use ($someLongVariableName, $anotherLongVariableName, $yetAnotherLongVariableName, $andOneMoreLongVariableName) {};\n    }\n}\n\n?>\n", "<?php\n\nclass SomeClass\n{\n    public function someFunction() {\n        $someLongVariableName = $anotherLongVariableName = $yetAnotherLongVariableName = $andOneMoreLongVariableName = null;\n\n        return function () use (\n            $someLongVariableName,\n            $anotherLongVariableName,\n            $yetAnotherLongVariableName,\n            $andOneMoreLongVariableName\n        ) {};\n\n        return function ($argument) use (\n            $someLongVariableName,\n            $anotherLongVariableName,\n            $yetAnotherLongVariableName,\n            $andOneMoreLongVariableName\n        ) {};\n    }\n}\n\n?>\n"},
		{"wrong", "<?php\n\nclass SomeClass\n{\n    public function someFunction(SomeLongArgument $someLongArgument, AnotherLongArgument $anotherLongArgument, $passTheLimit)\n    {\n    }\n\n    public function someFineFunction(SomeLongArgument $someLongArgumentFine, AnotherLongArgument $anotherLongArgumentTo)\n    {\n    }\n\n    public function someLongFunction(SomeLongArgument $someLongArgumentNotFine, AnotherLongArgument $anotherLongArgument)\n    {\n    }\n}\n\n?>\n", "<?php\n\nclass SomeClass\n{\n    public function someFunction(\n        SomeLongArgument $someLongArgument,\n        AnotherLongArgument $anotherLongArgument,\n        $passTheLimit\n    )\n    {\n    }\n\n    public function someFineFunction(SomeLongArgument $someLongArgumentFine, AnotherLongArgument $anotherLongArgumentTo)\n    {\n    }\n\n    public function someLongFunction(\n        SomeLongArgument $someLongArgumentNotFine,\n        AnotherLongArgument $anotherLongArgument\n    )\n    {\n    }\n}\n\n?>\n"},
		{"wrong10", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        if (something) {\n            throw new SomeException(sprintf('SuperLongMethod', 'SuperLongMethod', 'SuperLongMethod', 'SuperLongMethod'));\n        }\n    }\n}\n\n?>\n", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        if (something) {\n            throw new SomeException(sprintf(\n                'SuperLongMethod',\n                'SuperLongMethod',\n                'SuperLongMethod',\n                'SuperLongMethod'\n            ));\n        }\n    }\n}\n\n?>\n"},
		{"wrong11", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        return $this->assertSame(\n            $parameterProvider->provide(),\n            [\n                'one' => 1,\n                'two' => 2,\n            ]\n        );\n    }\n}\n\n?>\n", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        return $this->assertSame($parameterProvider->provide(), [\n                'one' => 1,\n                'two' => 2,\n            ]);\n    }\n}\n\n?>\n"},
		{"wrong12", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        yield \\Namespace1\\Namespace2\\Namespace3\\Namespace4\\Namespace5\\Namespace6\\MyClass::someLongStaticMethod(self::getArgument($parameter), self::getArgument($parameter));\n    }\n}\n\n?>\n", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        yield \\Namespace1\\Namespace2\\Namespace3\\Namespace4\\Namespace5\\Namespace6\\MyClass::someLongStaticMethod(\n            self::getArgument($parameter),\n            self::getArgument($parameter)\n        );\n    }\n}\n\n?>\n"},
		{"wrong13", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        yield CreateRoleCommand::fromValueObjects(RoleId::fromString(self::REALTY_ECONOMY), 'Předpisář', ScopeId::fromString(ScopeList::REALTY), PrivilegeList::REALTY_PRIVILEGES);\n    }\n}\n\n?>\n", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        yield CreateRoleCommand::fromValueObjects(\n            RoleId::fromString(self::REALTY_ECONOMY),\n            'Předpisář',\n            ScopeId::fromString(ScopeList::REALTY),\n            PrivilegeList::REALTY_PRIVILEGES\n        );\n    }\n}\n\n?>\n"},
		{"wrong14", "<?php\n\n$array = ['looooooooooooooooooooooooooooooooongArraaaaaaaaaaay', 'looooooooooooooooooooooooooooooooongArraaaaaaaaaaaaaaay'];\n\n?>\n", "<?php\n\n$array = [\n    'looooooooooooooooooooooooooooooooongArraaaaaaaaaaay',\n    'looooooooooooooooooooooooooooooooongArraaaaaaaaaaaaaaay'\n];\n\n?>\n"},
		{"wrong15", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        $result = ['loooooooooooooooooooooooooooooooongArraaaaaaaaaaay', 'loooooooooooooooooooooongArraaaaaaaaaaaaaaay'];\n    }\n}\n\n?>\n", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        $result = [\n            'loooooooooooooooooooooooooooooooongArraaaaaaaaaaay',\n            'loooooooooooooooooooooongArraaaaaaaaaaaaaaay'\n        ];\n    }\n}\n\n?>\n"},
		{"wrong16", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        return [\n            # form chain method calls\n            [__DIR__ . '/NestedMethodCallSource/FormChainMethodCalls.php.inc', 0, 'addRule', ['Stub_Nette\\Forms\\Rules']],\n        ];\n    }\n}\n\n?>\n", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        return [\n            # form chain method calls\n            [\n                __DIR__ . '/NestedMethodCallSource/FormChainMethodCalls.php.inc',\n                0,\n                'addRule',\n                ['Stub_Nette\\Forms\\Rules']\n            ],\n        ];\n    }\n}\n\n?>\n"},
		{"wrong18", "<?php\n\nclass A\n{\n    public function __construct($orWhere)\n    {\n        $sql = 'UPDATE answer \n                SET score = score + __points__ * (\n                        SELECT COUNT(aa.id) \n                        FROM answer_to_answer_definition aa \n                        WHERE answer.id = aa.pickX_answer_id AND ('.implode(' OR ', $orWhere).') AND answer.stuff IN (1, 2, 3, 4)\n                ).';\n    }\n}\n?>\n", "<?php\n\nclass A\n{\n    public function __construct($orWhere)\n    {\n        $sql = 'UPDATE answer \n                SET score = score + __points__ * (\n                        SELECT COUNT(aa.id) \n                        FROM answer_to_answer_definition aa \n                        WHERE answer.id = aa.pickX_answer_id AND ('.implode(\n                            ' OR ',\n                            $orWhere\n                        ).') AND answer.stuff IN (1, 2, 3, 4)\n                ).';\n    }\n}\n?>\n"},
		{"wrong2", "<?php\n\nclass SomeClass\n{\n    public function someFunction(\n        SomeLongArgument $someLongArgument,\n        AnotherLongArgument $anotherLongArgument\n    ) {\n    }\n\n    public function someOtherFunction(\n        SomeLongArgument $someLongArgument,\n        AnotherLongArgument $anotherLongArgument,\n        LongOneArgument $longOneArgument\n    ) {\n    }\n}\n\n?>\n", "<?php\n\nclass SomeClass\n{\n    public function someFunction(SomeLongArgument $someLongArgument, AnotherLongArgument $anotherLongArgument) {\n    }\n\n    public function someOtherFunction(\n        SomeLongArgument $someLongArgument,\n        AnotherLongArgument $anotherLongArgument,\n        LongOneArgument $longOneArgument\n    ) {\n    }\n}\n\n?>\n"},
		{"wrong8", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        $this->assertSame(['one' => 1, 'two' => 2, 'fooooooooooooooooooo' => 'baaaaaar'], $parameterProvider->provide());\n    }\n}\n\n?>\n", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        $this->assertSame(\n            ['one' => 1, 'two' => 2, 'fooooooooooooooooooo' => 'baaaaaar'],\n            $parameterProvider->provide()\n        );\n    }\n}\n\n?>\n"},
		{"wrong9", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        foreach ($finder as $fileInfo) {\n            $processInput[] = sprintf('%s=%s', $fileInfo->getRelativePathname(), $newPackageDirectory . '/' . $fileInfo->getRelativePathname());\n        }\n    }\n}\n\n?>\n", "<?php\n\nclass SomeClass\n{\n    public function someFunction()\n    {\n        foreach ($finder as $fileInfo) {\n            $processInput[] = sprintf(\n                '%s=%s',\n                $fileInfo->getRelativePathname(),\n                $newPackageDirectory . '/' . $fileInfo->getRelativePathname()\n            );\n        }\n    }\n}\n\n?>\n"},
		{"wrong_array_bracket_position_in_arg_list", "<?php\n\nclass Bar\n{\n    public function foo(string $arg1, string $arg2, string $arg3, string $arg4, string $arg5, string $arg6, array $arg7 = []): void\n    {\n        // Do stuff\n    }\n}\n?>\n", "<?php\n\nclass Bar\n{\n    public function foo(\n        string $arg1,\n        string $arg2,\n        string $arg3,\n        string $arg4,\n        string $arg5,\n        string $arg6,\n        array $arg7 = []\n    ): void\n    {\n        // Do stuff\n    }\n}\n?>\n"},
		// a short multiline __construct is left to StandaloneLineConstructorParamFixer,
		// not inlined - matches PHP ECS, which skips __construct in LineLengthFixer
		{"skip_short_constructor", "<?php\n\nclass A\n{\n    public function __construct(\n        string $rectorClass\n    ) {\n    }\n}\n", "<?php\n\nclass A\n{\n    public function __construct(\n        string $rectorClass\n    ) {\n    }\n}\n"},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, changed := apply(t, LineLength{}, tc.in)
			if got != tc.want {
				t.Fatalf("got:\n%q\nwant:\n%q", got, tc.want)
			}
			if wantChanged := tc.in != tc.want; changed != wantChanged {
				t.Fatalf("changed=%v want=%v", changed, wantChanged)
			}
		})
	}
}
